+  <script src="/delivery-crypto.js"></script>
+  <script>
+    (function () {
+      'use strict';
+
+      const CryptoEngine = window.DailyGrindCrypto;
+      if (!CryptoEngine) return;
+
+      // State
+      let recipientKeyBundle = null;
+      let currentValidEnvelope = null;
+      let activeWorkingEnvelope = null;
+      let savedEnvelopes = [];
+
+      // DOM Elements
+      const suiteSelect = document.getElementById('crypto-suite');
+      const orderRefInput = document.getElementById('order-ref');
+      const dropoffTypeSelect = document.getElementById('dropoff-type');
+      const deliveryWindowSelect = document.getElementById('delivery-window');
+      const noteInput = document.getElementById('delivery-note-input');
+      const encryptForm = document.getElementById('encrypted-note-form');
+      const rotateKeysBtn = document.getElementById('rotate-keys-btn');
+      const copyEnvelopeBtn = document.getElementById('copy-envelope-btn');
+      const encryptStatusMsg = document.getElementById('encrypt-status-msg');
+
+      const recipientKeyIdEl = document.getElementById('recipient-key-id');
+      const recipientFingerprintEl = document.getElementById('recipient-key-fingerprint');
+      const activeSuiteBadge = document.getElementById('active-suite-badge');
+      const telemetryBitsBadge = document.getElementById('telemetry-bits-badge');
+
+      const stepClassicalCard = document.getElementById('step-classical-card');
+      const telemetryClassicalCurve = document.getElementById('telemetry-classical-curve');
+      const telemetryEphemeralLen = document.getElementById('telemetry-ephemeral-len');
+      const telemetryEphemeralPub = document.getElementById('telemetry-ephemeral-pub');
+
+      const stepPqCard = document.getElementById('step-pq-card');
+      const telemetryPqAlg = document.getElementById('telemetry-pq-alg');
+      const telemetryKemLen = document.getElementById('telemetry-kem-len');
+      const telemetryKemCapsule = document.getElementById('telemetry-kem-capsule');
+
+      const sharedSecretCommitmentEl = document.getElementById('shared-secret-commitment');
+      const aeadIvEl = document.getElementById('aead-iv');
+      const aeadTagEl = document.getElementById('aead-tag');
+      const aeadCiphertextEl = document.getElementById('aead-ciphertext');
+      const aeadAadEl = document.getElementById('aead-aad');
+      const envelopeJsonPre = document.getElementById('encrypted-envelope-json');
+
+      const decryptNoteBtn = document.getElementById('decrypt-note-btn');
+      const tamperCiphertextBtn = document.getElementById('tamper-ciphertext-btn');
+      const tamperKemBtn = document.getElementById('tamper-kem-btn');
+      const tamperAadBtn = document.getElementById('tamper-aad-btn');
+      const restoreEnvelopeBtn = document.getElementById('restore-envelope-btn');
+
+      const statusBanner = document.getElementById('decryption-status-banner');
+      const statusTitle = document.getElementById('decryption-status-title');
+      const statusDetail = document.getElementById('decryption-status-detail');
+      const decryptedPlaintextOutput = document.getElementById('decrypted-plaintext-output');
+
+      const savedNotesCountEl = document.getElementById('saved-notes-count');
+      const savedNotesListEl = document.getElementById('encrypted-notes-list');
+
+      function truncateMiddle(str, startLen = 28, endLen = 20) {
+        if (!str) return '—';
+        if (str.length <= startLen + endLen + 5) return str;
+        return str.slice(0, startLen) + ' ... ' + str.slice(-endLen);
+      }
+
+      function renderKeyringInfo() {
+        if (!recipientKeyBundle) return;
+        recipientKeyIdEl.textContent = recipientKeyBundle.keyId;
+        recipientFingerprintEl.textContent = recipientKeyBundle.fingerprint;
+      }
+
+      function renderTelemetry(envelope) {
+        if (!envelope) return;
+        const ke = envelope.keyEstablishment;
+
+        activeSuiteBadge.textContent = envelope.suiteName;
+        telemetryBitsBadge.textContent = `${ke.sharedSecretLengthBits}-bit Shared Secret IKM → 256-bit AES-GCM`;
+
+        // Classical ECDH step
+        if (ke.ephemeralPublicKey) {
+          stepClassicalCard.style.opacity = '1';
+          telemetryClassicalCurve.textContent = `ECDH ${ke.classicalCurve}`;
+          telemetryEphemeralLen.textContent = `${ke.ephemeralPublicKeyBytes} Bytes`;
+          telemetryEphemeralPub.textContent =
+            `Pub: ${truncateMiddle(ke.ephemeralPublicKey, 24, 16)} | Secret SHA3: ${ke.classicalSecretDigest}`;
+        } else {
+          stepClassicalCard.style.opacity = '0.5';
+          telemetryClassicalCurve.textContent = 'Not Used (Pure PQ Mode)';
+          telemetryEphemeralLen.textContent = '0 Bytes';
+          telemetryEphemeralPub.textContent = 'Skipped — Relying solely on post-quantum ML-KEM-768 encapsulation';
+        }
+
+        // Post-Quantum ML-KEM-768 step
+        if (ke.kemCiphertext) {
+          stepPqCard.style.opacity = '1';
+          telemetryPqAlg.textContent = `${ke.pqKem} (FIPS 203)`;
+          telemetryKemLen.textContent = `${ke.kemCiphertextBytes} Bytes`;
+          telemetryKemCapsule.textContent =
+            `Capsule: ${truncateMiddle(ke.kemCiphertext, 24, 16)} | Secret SHA3: ${ke.pqSecretDigest}`;
+        } else {
+          stepPqCard.style.opacity = '0.5';
+          telemetryPqAlg.textContent = 'Not Used (Classical Mode)';
+          telemetryKemLen.textContent = '0 Bytes';
+          telemetryKemCapsule.textContent = 'Skipped — Relying solely on classical ECDH key agreement';
+        }
+
+        sharedSecretCommitmentEl.textContent = `${ke.keyCommitment} (HKDF Salt: ${ke.hkdfSalt})`;
+        aeadIvEl.textContent = envelope.iv;
+        aeadTagEl.textContent = envelope.authTag;
+        aeadCiphertextEl.textContent = envelope.ciphertext;
+        aeadAadEl.textContent = JSON.stringify(envelope.aad);
+        envelopeJsonPre.textContent = JSON.stringify(envelope, null, 2);
+      }
+
+      async function verifyAndDisplayDecryption(envelopeToTest, actionLabel = '') {
+        if (!envelopeToTest || !recipientKeyBundle) return;
+        try {
+          const result = await CryptoEngine.decryptDeliveryNote({
+            envelope: envelopeToTest,
+            recipientPrivateKeys: recipientKeyBundle.privateKeys
+          });
+          statusBanner.className = 'status-banner verified';
+          statusTitle.textContent =
+            `Authenticated & Verified (${result.suite})`;
+          statusDetail.textContent =
+            `${actionLabel ? actionLabel + ' — ' : ''}Key Commitment ${result.keyCommitment} matched. 128-bit AES-256-GCM tag & AAD verified.`;
+          decryptedPlaintextOutput.style.display = 'block';
+          decryptedPlaintextOutput.textContent = result.plaintext;
+        } catch (err) {
+          statusBanner.className = 'status-banner tampered';
+          statusTitle.textContent = 'Decryption Rejected: Integrity / Authentication Failure';
+          statusDetail.textContent =
+            `${actionLabel ? actionLabel + ' — ' : ''}${err.message}`;
+          decryptedPlaintextOutput.style.display = 'none';
+          decryptedPlaintextOutput.textContent = '';
+        }
+      }
+
+      function renderSavedNotesList() {
+        savedNotesCountEl.textContent = String(savedEnvelopes.length);
+        savedNotesListEl.innerHTML = '';
+        savedEnvelopes.forEach((item, idx) => {
+          const card = document.createElement('div');
+          card.className = 'saved-note-item';
+          card.innerHTML = `
+            <div>
+              <div class="saved-note-header">
+                <span>${item.envelope.aad.orderRef} (${item.envelope.aad.dropoffType})</span>
+                <span class="badge" style="font-size: 0.68rem;">${item.envelope.suite}</span>
+              </div>
+              <div style="font-size: 0.78rem; color: var(--text-muted); margin-top: 4px;">
+                Window: ${item.envelope.aad.deliveryWindow}
+              </div>
+              <div class="mono-val" style="margin-top: 6px;">
+                Ciphertext: ${truncateMiddle(item.envelope.ciphertext, 20, 14)}
+              </div>
+              <div style="font-size: 0.75rem; color: #2e7d32; margin-top: 4px;">
+                Commitment: <code>${item.envelope.keyEstablishment.keyCommitment.slice(0, 16)}...</code>
+              </div>
+            </div>
+            <div style="display: flex; gap: 6px; margin-top: 6px;">
+              <button type="button" class="btn btn-secondary btn-sm inspect-saved-btn" data-index="${idx}">
+                Load &amp; Decrypt in Inspector
+              </button>
+            </div>
+          `;
+          savedNotesListEl.appendChild(card);
+        });
+
+        savedNotesListEl.querySelectorAll('.inspect-saved-btn').forEach((btn) => {
+          btn.addEventListener('click', async () => {
+            const idx = Number(btn.getAttribute('data-index'));
+            const selected = savedEnvelopes[idx];
+            if (!selected) return;
+            recipientKeyBundle = selected.keyBundleSnapshot;
+            currentValidEnvelope = JSON.parse(JSON.stringify(selected.envelope));
+            activeWorkingEnvelope = JSON.parse(JSON.stringify(selected.envelope));
+            renderKeyringInfo();
+            renderTelemetry(activeWorkingEnvelope);
+            await verifyAndDisplayDecryption(activeWorkingEnvelope, `Loaded ${selected.envelope.aad.orderRef}`);
+          });
+        });
+      }
+
+      async function handleEncryptNote(statusNote = 'Encrypted with fresh ephemeral keys') {
+        if (!recipientKeyBundle) {
+          recipientKeyBundle = await CryptoEngine.generateRecipientKeyBundle();
+          renderKeyringInfo();
+        }
+        const suiteId = suiteSelect.value;
+        const noteText = noteInput.value.trim() || 'Leave coffee by front planter box.';
+        const metadata = {
+          orderRef: orderRefInput.value.trim() || 'ORD-8492',
+          dropoffType: dropoffTypeSelect.value,
+          deliveryWindow: deliveryWindowSelect.value,
+          timestamp: new Date().toISOString()
+        };
+
+        const envelope = await CryptoEngine.encryptDeliveryNote({
+          noteText,
+          metadata,
+          suiteId,
+          recipientPublicKeys: recipientKeyBundle.publicKeys,
+          recipientKeyId: recipientKeyBundle.keyId
+        });
+
+        currentValidEnvelope = JSON.parse(JSON.stringify(envelope));
+        activeWorkingEnvelope = JSON.parse(JSON.stringify(envelope));
+
+        savedEnvelopes.unshift({
+          envelope: JSON.parse(JSON.stringify(envelope)),
+          keyBundleSnapshot: JSON.parse(JSON.stringify(recipientKeyBundle))
+        });
+        if (savedEnvelopes.length > 6) savedEnvelopes.pop();
+
+        renderTelemetry(activeWorkingEnvelope);
+        renderSavedNotesList();
+        await verifyAndDisplayDecryption(activeWorkingEnvelope, statusNote);
+
+        encryptStatusMsg.textContent = `✓ ${statusNote}`;
+        setTimeout(() => {
+          if (encryptStatusMsg.textContent === `✓ ${statusNote}`) {
+            encryptStatusMsg.textContent = '';
+          }
+        }, 4000);
+      }
+
+      // Event Listeners
+      encryptForm.addEventListener('submit', async (e) => {
+        e.preventDefault();
+        await handleEncryptNote('New shared secret established & note encrypted');
+      });
+
+      suiteSelect.addEventListener('change', async () => {
+        await handleEncryptNote(`Switched suite to ${suiteSelect.value}`);
+      });
+
+      rotateKeysBtn.addEventListener('click', async () => {
+        const suffix = Math.floor(1000 + Math.random() * 9000);
+        recipientKeyBundle = await CryptoEngine.generateRecipientKeyBundle(`dg-courier-hub-${suffix}`);
+        renderKeyringInfo();
+        await handleEncryptNote(`Rotated courier keyring (${recipientKeyBundle.fingerprint})`);
+      });
+
+      document.querySelectorAll('.chip[data-template]').forEach((chip) => {
+        chip.addEventListener('click', async () => {
+          noteInput.value = chip.getAttribute('data-template');
+          await handleEncryptNote('Encrypted preset delivery note');
+        });
+      });
+
+      copyEnvelopeBtn.addEventListener('click', async () => {
+        if (!activeWorkingEnvelope) return;
+        const jsonStr = JSON.stringify(activeWorkingEnvelope, null, 2);
+        if (navigator.clipboard && navigator.clipboard.writeText) {
+          try {
+            await navigator.clipboard.writeText(jsonStr);
+            encryptStatusMsg.textContent = '✓ Copied encrypted JSON envelope';
+            return;
+          } catch (_e) {
+            // fallback
+          }
+        }
+        encryptStatusMsg.textContent = '✓ Envelope ready in inspector';
+      });
+
+      decryptNoteBtn.addEventListener('click', async () => {
+        await verifyAndDisplayDecryption(activeWorkingEnvelope, 'Manual verification');
+      });
+
+      tamperCiphertextBtn.addEventListener('click', async () => {
+        if (!currentValidEnvelope) return;
+        activeWorkingEnvelope = JSON.parse(JSON.stringify(currentValidEnvelope));
+        const ctBytes = CryptoEngine.utils.base64ToBytes(activeWorkingEnvelope.ciphertext);
+        ctBytes[0] ^= 0x01; // Flip 1 bit in AES-GCM ciphertext
+        activeWorkingEnvelope.ciphertext = CryptoEngine.utils.bytesToBase64(ctBytes);
+        renderTelemetry(activeWorkingEnvelope);
+        await verifyAndDisplayDecryption(activeWorkingEnvelope, 'Tampered 1 bit in AES-GCM Ciphertext');
+      });
+
+      tamperKemBtn.addEventListener('click', async () => {
+        if (!currentValidEnvelope) return;
+        activeWorkingEnvelope = JSON.parse(JSON.stringify(currentValidEnvelope));
+        const ke = activeWorkingEnvelope.keyEstablishment;
+        if (ke.kemCiphertext) {
+          const kemBytes = CryptoEngine.utils.base64ToBytes(ke.kemCiphertext);
+          kemBytes[4] ^= 0x01; // Flip 1 bit in ML-KEM-768 capsule -> triggers FIPS 203 implicit rejection
+          ke.kemCiphertext = CryptoEngine.utils.bytesToBase64(kemBytes);
+          renderTelemetry(activeWorkingEnvelope);
+          await verifyAndDisplayDecryption(activeWorkingEnvelope, 'Tampered 1 bit in ML-KEM-768 Capsule');
+        } else if (ke.ephemeralPublicKey) {
+          const pubBytes = CryptoEngine.utils.base64ToBytes(ke.ephemeralPublicKey);
+          pubBytes[pubBytes.length - 1] ^= 0x01;
+          ke.ephemeralPublicKey = CryptoEngine.utils.bytesToBase64(pubBytes);
+          renderTelemetry(activeWorkingEnvelope);
+          await verifyAndDisplayDecryption(activeWorkingEnvelope, 'Tampered Ephemeral ECDH Public Key');
+        }
+      });
+
+      tamperAadBtn.addEventListener('click', async () => {
+        if (!currentValidEnvelope) return;
+        activeWorkingEnvelope = JSON.parse(JSON.stringify(currentValidEnvelope));
+        activeWorkingEnvelope.aad.orderRef = activeWorkingEnvelope.aad.orderRef + '-MODIFIED';
+        renderTelemetry(activeWorkingEnvelope);
+        await verifyAndDisplayDecryption(activeWorkingEnvelope, 'Tampered Additional Authenticated Data (AAD)');
+      });
+
+      restoreEnvelopeBtn.addEventListener('click', async () => {
+        if (!currentValidEnvelope) return;
+        activeWorkingEnvelope = JSON.parse(JSON.stringify(currentValidEnvelope));
+        renderTelemetry(activeWorkingEnvelope);
+        await verifyAndDisplayDecryption(activeWorkingEnvelope, 'Restored original untampered envelope');
+      });
+
+      // Initialize on page load
+      (async function init() {
+        recipientKeyBundle = await CryptoEngine.generateRecipientKeyBundle('dg-courier-hub-2026-q4');
+        renderKeyringInfo();
+        await handleEncryptNote('Initial hybrid PQ shared secret established');
+      })();
+    })();
+  </script>
