+// Iterative + capped recursion radiance to safely stay within stack limits
+Vec radiance(const Ray &r_, int depth_, unsigned short *Xi) {
+  double t;   // distance to intersection
+  int id = 0; // id of intersected sphere
+  if (!intersect(r_, t, id))
