+      (r_.d * nnt - n * ((into ? 1 : -1) * (ddn * nnt + sqrt(cos2t)))).norm();
+  double a = nt - nc, b = nt + nc, R0 = a * a / (b * b),
+         c = 1 - (into ? -ddn : tdir.dot(n));
+  double Re = R0 + (1 - R0) * c * c * c * c * c, Tr = 1 - Re, P = .25 + .5 * Re,
+         RP = Re / P, TP = Tr / (1 - P);
+  return obj.e +
+         f.mult(depth_ > 2
+                    ? (erand48(Xi) < P ? // Russian roulette
+                           radiance(reflRay, depth_, Xi) * RP
+                                       : radiance(Ray(x, tdir), depth_, Xi) * TP)
+                    : radiance(reflRay, depth_, Xi) * Re +
+                          radiance(Ray(x, tdir), depth_, Xi) * Tr);
