+// Update sphere colors from a flat array of 8 * 3 = 24 doubles (for spheres 0..7, keeping sphere 8 as the light source)
+void set_sphere_colors(const double *colors, int count) {
+  int max_spheres = count < 8 ? count : 8;
+  for (int i = 0; i < max_spheres; ++i) {
+    spheres[i].c = Vec(colors[i * 3 + 0], colors[i * 3 + 1], colors[i * 3 + 2]);
+  }
