+        color: #94a3b8;
+        margin-bottom: 0.375rem;
+      }
+      .progress-track {
+        width: 100%;
+        height: 0.375rem;
+        background: #0f172a;
+        border-radius: 9999px;
+        overflow: hidden;
+      }
+      .progress-bar {
+        height: 100%;
+        background: #fbbf24;
+        width: 0%;
+        transition: width 0.2s ease;
