+      };
+
+      btn.addEventListener('click', () => {
+        clickCount += 1;
+        const rand = crypto.getRandomValues(new Uint32Array(1))[0];
+        const seed = (rand ^ (clickCount * 2654435761)) >>> 0;
+        container.dataset.status = 'rendering';
+        dot.classList.remove('complete');
+        worker.postMessage({
+          type: 'render',
+          width: 320,
+          height: 240,
+          sampsPerPass: 1,
+          targetPasses: 4,
+          randomize: true,
+          seed,
+        });
+      });
+
+      container.dataset.status = 'rendering';
+      worker.postMessage({
+        type: 'render',
+        width: 320,
+        height: 240,
+        sampsPerPass: 1,
+        targetPasses: 4,
+        randomize: false,
+      });
+    </script>
