+      // =========================================================================
+      // POST-QUANTUM SCHEME 2: PQC-WOTS-SHA256 (Winternitz Hash-Based Signature)
+      // =========================================================================
+      // Uses 32 base-16 message nibbles (128-bit folded SHA-256 digest) + 3 base-16 checksum nibbles = 35 hash chains of length w=16.
+      const WOTS_MSG_CHAINS = 32;
+      const WOTS_CSUM_CHAINS = 3;
+      const WOTS_TOTAL_CHAINS = WOTS_MSG_CHAINS + WOTS_CSUM_CHAINS; // 35 chains
+      const WOTS_W = 16; // Base-16 Winternitz parameter (steps 0..15)
