+        // Fold 64-char SHA-256 hex into 32 hex nibbles via XOR so all 256 bits of SHA-256 are bound
+        const digits = new Array(WOTS_TOTAL_CHAINS);
+        let checksum = 0;
+        for (let i = 0; i < WOTS_MSG_CHAINS; i++) {
+          const n1 = parseInt(messageHashHex[i], 16) || 0;
+          const n2 = parseInt(messageHashHex[i + 32], 16) || 0;
+          const d = n1 ^ n2;
+          digits[i] = d;
+          checksum += (WOTS_W - 1 - d);
+        }
