+
+    document.querySelectorAll('.redeem-btn').forEach(btn => {
+      btn.addEventListener('click', () => {
+        const cost = Number(btn.dataset.cost);
+        const isRedeemed = btn.getAttribute('aria-pressed') === 'true';
+        if (!isRedeemed) {
+          if (currentBeans >= cost) {
+            currentBeans -= cost;
+            btn.setAttribute('aria-pressed', 'true');
+            btn.textContent = 'Reward Applied';
+            rewardsStatus.textContent = `Redeemed ${cost} Beans! Applied to your next order.`;
+          } else {
+            rewardsStatus.textContent = 'Not enough Beans for this reward.';
+          }
+        } else {
+          currentBeans += cost;
+          btn.setAttribute('aria-pressed', 'false');
+          btn.textContent = `Redeem ${cost} Beans`;
+          rewardsStatus.textContent = `Refunded ${cost} Beans to your balance.`;
+        }
+        balanceEl.textContent = String(currentBeans);
+        progressEl.value = currentBeans;
+      });
+    });
+
+    // Interactive Account preferences save state
+    const accountForm = document.getElementById('account-form');
+    const accountStatus = document.getElementById('account-status');
+
