+    <script>
+        const VALID_VIEWS = ['all', 'top-news', 'world', 'politics', 'multimedia', 'reports'];
+
+        function switchToView(viewId: string, options: { updateHistory?: boolean; focusView?: boolean } = {}) {
+            const { updateHistory = true, focusView = true } = options;
+            const normalizedId = VALID_VIEWS.includes(viewId) ? viewId : 'all';
+            const targetElementId = `view-${normalizedId}`;
+            const activeView = document.getElementById(targetElementId);
+            if (!activeView) return;
+
+            const performDomSwitch = () => {
+                // Hide all views while preserving their rendered DOM state via content-visibility: hidden
+                document.querySelectorAll<HTMLElement>('.spa-view').forEach((view) => {
+                    if (view.id !== targetElementId) {
+                        view.classList.add('inactive');
+                        view.setAttribute('aria-hidden', 'true');
+                        view.setAttribute('inert', 'inert');
+                    }
+                });
+
+                // Show the target view
+                activeView.classList.remove('inactive');
+                activeView.setAttribute('aria-hidden', 'false');
+                activeView.removeAttribute('inert');
+            };
+
+            performDomSwitch();
+
+            if (focusView) {
+                activeView.focus({ preventScroll: true });
+            }
+
+            if (updateHistory) {
+                const url = new URL(window.location.href);
+                if (normalizedId === 'all') {
+                    url.searchParams.delete('section');
+                    url.hash = '';
+                } else {
+                    url.searchParams.set('section', normalizedId);
+                    url.hash = normalizedId;
+                }
+                window.history.pushState({ viewId: normalizedId }, '', url.toString());
+            }
+
+            window.dispatchEvent(new CustomEvent('spa-view-changed', { detail: { viewId: normalizedId } }));
+        }
+
+        function setupSpaNavigation() {
+            // Setup client-side filter inputs inside Multimedia and Reports views (demonstrating preserved DOM state across switches)
+            document.querySelectorAll<HTMLInputElement>('[data-view-filter]').forEach((input) => {
+                if (input.dataset.bound === 'true') return;
+                input.dataset.bound = 'true';
+                input.addEventListener('input', () => {
+                    const listName = input.getAttribute('data-view-filter');
+                    const query = input.value.trim().toLowerCase();
+                    const list = document.querySelector(`[data-filter-list="${listName}"]`);
+                    if (!list) return;
+                    list.querySelectorAll<HTMLElement>('[data-filter-item]').forEach((item) => {
+                        const title = item.getAttribute('data-title') || '';
+                        const category = item.getAttribute('data-category') || '';
+                        const matches = !query || title.includes(query) || category.includes(query);
