+          -0.5, -0.5, 0.0,      0.0, 1.0,
+           0.5,  0.5, 0.0,      1.0, 0.0,
+          -0.5,  0.5, 0.0,      0.0, 0.0,
+        ]);
+
+        quadVao = gl.createVertexArray();
+        gl.bindVertexArray(quadVao);
+
+        const vbo = gl.createBuffer();
+        gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
+        gl.bufferData(gl.ARRAY_BUFFER, quadVertices, gl.STATIC_DRAW);
+
+        gl.enableVertexAttribArray(0);
+        gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 5 * 4, 0);
+        gl.enableVertexAttribArray(1);
+        gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 5 * 4, 3 * 4);
+        gl.bindVertexArray(null);
+
+        formTexture = gl.createTexture();
+        sideTexture = gl.createTexture();
+        updateSidePackagingTexture('light');
+
+        // Initialize fallback placeholder pixels in formTexture until first upload
+        allocateElementTexture(gl, formTexture, formTextureState, 2, 2);
+      }
+
+      // Configure HTML-in-Canvas mode or Fallback Strategy for unsupported browsers
+      if (supportsHtmlInCanvas) {
+        modeBadge.textContent = 'HTML-in-Canvas 3D Projection Active';
+      } else {
