+      }
+
+      // Rotation state & interactive controls
+      let isAutoRotating = true;
+      let userYawOffset = 0;
+      let userPitchOffset = 0;
+      let autoTime = 0;
+      let lastFrameTime = performance.now();
+      let currentYaw = 0;
+      let currentPitch = 0;
+
+      // Coffee box 3D dimensions (proportioned to the 360x530 form card)
+      const boxWidth = 1.68;
+      const boxHeight = 2.42;
+      const boxDepth = 0.82;
+
+      function renderCoffeeBoxScene() {
+        const clientW = canvas.clientWidth || 800;
+        const clientH = canvas.clientHeight || 680;
+        const aspect = clientW / clientH;
+
+        const projection = mat4Perspective((42 * Math.PI) / 180, aspect, 0.1, 25.0);
+        const view = mat4Translate(0, 0, -4.15);
+        const boxRotation = mat4Multiply(mat4RotateX(currentPitch), mat4RotateY(currentYaw));
+        const viewBox = mat4Multiply(view, boxRotation);
+
+        // Front face transform: sits at +boxDepth/2 and scales unit quad (-0.5..0.5) to (boxWidth, boxHeight)
+        const frontLocal = mat4Multiply(
+          mat4Translate(0, 0, boxDepth / 2),
+          mat4Scale(boxWidth, boxHeight, 1)
+        );
+        const htmlElementMVP = mat4Multiply(projection, mat4Multiply(viewBox, frontLocal));
+
+        if (gl && shaderProgram) {
+          gl.viewport(0, 0, canvas.width || clientW, canvas.height || clientH);
+          gl.clearColor(0.11, 0.06, 0.05, 1.0);
+          gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
+          gl.enable(gl.DEPTH_TEST);
+
+          gl.useProgram(shaderProgram);
+          gl.bindVertexArray(quadVao);
+          gl.activeTexture(gl.TEXTURE0);
+          gl.uniform1i(uTextureLoc, 0);
+
+          // Helper to draw a face of the 3D coffee box
+          const drawFace = (faceLocalMatrix, texture, shade) => {
+            const mvp = mat4Multiply(projection, mat4Multiply(viewBox, faceLocalMatrix));
+            gl.bindTexture(gl.TEXTURE_2D, texture);
+            gl.uniformMatrix4fv(uMvpLoc, false, mvp);
+            gl.uniform1f(uShadeLoc, shade);
+            gl.drawArrays(gl.TRIANGLES, 0, 6);
+          };
+
+          // 1. Front face (HTML Form Texture when HTML-in-Canvas is active, or packaging face in fallback)
+          drawFace(
+            frontLocal,
+            supportsHtmlInCanvas && hasUploadedFormTexture ? formTexture : sideTexture,
+            1.0
+          );
+
+          // 2. Back face
+          const backLocal = mat4Multiply(
+            mat4Multiply(mat4Translate(0, 0, -boxDepth / 2), mat4RotateY(Math.PI)),
+            mat4Scale(boxWidth, boxHeight, 1)
+          );
+          drawFace(backLocal, sideTexture, 0.65);
+
+          // 3. Right face
+          const rightLocal = mat4Multiply(
+            mat4Multiply(mat4Translate(boxWidth / 2, 0, 0), mat4RotateY(Math.PI / 2)),
+            mat4Scale(boxDepth, boxHeight, 1)
+          );
+          drawFace(rightLocal, sideTexture, 0.85);
+
+          // 4. Left face
+          const leftLocal = mat4Multiply(
+            mat4Multiply(mat4Translate(-boxWidth / 2, 0, 0), mat4RotateY(-Math.PI / 2)),
+            mat4Scale(boxDepth, boxHeight, 1)
+          );
+          drawFace(leftLocal, sideTexture, 0.80);
+
+          // 5. Top face
+          const topLocal = mat4Multiply(
+            mat4Multiply(mat4Translate(0, boxHeight / 2, 0), mat4RotateX(-Math.PI / 2)),
+            mat4Scale(boxWidth, boxDepth, 1)
+          );
+          drawFace(topLocal, sideTexture, 0.92);
+
+          // 6. Bottom face
+          const bottomLocal = mat4Multiply(
+            mat4Multiply(mat4Translate(0, -boxHeight / 2, 0), mat4RotateX(Math.PI / 2)),
+            mat4Scale(boxWidth, boxDepth, 1)
+          );
+          drawFace(bottomLocal, sideTexture, 0.55);
