+        lastFrameTime = now;
+
+        if (isAutoRotating) {
+          autoTime += dt;
+        }
+
+        // Smooth continuous 3D orbital rotation keeping the form front-facing and clickable
+        currentYaw = userYawOffset + Math.sin(autoTime * 0.85) * 0.36;
+        currentPitch = userPitchOffset + Math.cos(autoTime * 0.6) * 0.11;
+
+        if (supportsHtmlInCanvas && typeof canvas.requestPaint === 'function') {
+          canvas.requestPaint();
+        } else {
+          // Fallback: render WebGL 3D coffee box and sync CSS 3D transform on overlaid form
+          renderCoffeeBoxScene();
