+          emailError.hidden = true;
+        }
+        submitBtn.disabled = false;
+      });
+
+      emailInput.addEventListener('blur', () => {
+        if (emailEdited) {
+          validateEmailField();
+        }
+      });
+
+      // Secondary button ("Roaster's Pick") fills a curated preset
+      const presets = [
+        { name: 'Jordan Lee', email: 'jordan.lee@example.com', roast: 'light', wholeBean: true },
+        { name: 'Samira Patel', email: 'samira.patel@example.com', roast: 'medium', wholeBean: true },
