+        // Disable submit button after valid submission to prevent double-posts until next edit
+        submitBtn.disabled = true;
+        orderStatus.textContent = `Box reserved for ${recipient} (${selectedRoast} roast, ${grindType})!`;
+      });
+    })();
+  </script>
