+
+  // Handle CORS / Local Network Access preflight requests to local diagnostic endpoints
+  if (
+    context.request.method === 'OPTIONS' &&
+    context.request.headers.get('Access-Control-Request-Private-Network') === 'true'
+  ) {
+    const origin = context.request.headers.get('Origin') || '*';
+    return new Response(null, {
+      status: 204,
+      headers: {
+        'Access-Control-Allow-Origin': origin,
+        'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
+        'Access-Control-Allow-Headers': 'Content-Type, Accept, X-DevTools-Diagnostics',
+        'Access-Control-Allow-Private-Network': 'true',
+        'Permissions-Policy':
+          'local-network=(self), loopback-network=(self), local-network-access=(self)',
+      },
+    });
+  }
+
+  const response = await next();
+
+  // Grant Local Network Access permissions policy for both LAN (local-network)
+  // and localhost companion CLI (loopback-network) endpoints
+  if (!response.headers.has('Permissions-Policy')) {
+    response.headers.set(
+      'Permissions-Policy',
+      'local-network=(self), loopback-network=(self), local-network-access=(self)'
+    );
+  }
+
+  if (context.request.headers.get('Access-Control-Request-Private-Network') === 'true') {
+    response.headers.set('Access-Control-Allow-Private-Network', 'true');
+  }
+
+  return response;
 });
