+      // Update the visual summary badges on a seasonal drink card
+      function refreshCardSummary(cardId) {
+        if (!cardId) return;
+        const summaryContainer = document.querySelector(`[data-summary-for="${cardId}"]`);
+        if (!summaryContainer) return;
