+      // Full WAI-ARIA keyboard navigation for menus and nested submenus
+      document.addEventListener('keydown', (e) => {
+        const active = document.activeElement;
+        if (!active) return;
+
+        const inMenuContainer = active.closest('.menu-container');
+        if (!inMenuContainer) return;
+
+        const isRootTrigger = active.parentElement.classList.contains('menu-container');
+        const currentPopup = active.closest('.popup-menu');
