+        if (isRootTrigger) {
+          if (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === ' ') {
+            e.preventDefault();
+            openSubmenu(active, true);
+          } else if (e.key === 'Escape') {
+            closeSubmenu(active);
+          }
+          return;
+        }
