+import http from 'node:http';
+import fs from 'node:fs';
+import path from 'node:path';
+import os from 'node:os';
+import { parseArgs } from 'node:util';
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.webmanifest': 'application/manifest+json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.ico': 'image/x-icon',
+  '.txt': 'text/plain; charset=utf-8'
+};
+
+const { values, positionals } = parseArgs({
+  options: {
+    port: { type: 'string' },
+    expose: { type: 'boolean' },
+    cors: { type: 'boolean' },
+    coi: { type: 'boolean' },
+    csp: { type: 'string' },
+    help: { type: 'boolean' },
+    open: { type: 'boolean' }
+  },
+  allowPositionals: true,
+  strict: false
+});
+
+const rootDir = positionals[0] ? path.resolve(positionals[0]) : process.cwd();
+const rawPort = values.port ?? process.env.PORT ?? '11222';
+const initialPort = Number(rawPort) || 11222;
+
+const server = http.createServer((req, res) => {
+  res.setHeader('Access-Control-Allow-Origin', '*');
+  res.setHeader('Access-Control-Allow-Methods', 'GET, HEAD, OPTIONS');
+  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
+
+  if (req.method === 'OPTIONS') {
+    res.writeHead(204);
+    res.end();
+    return;
+  }
+
+  const parsedUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  let pathname = decodeURIComponent(parsedUrl.pathname);
+
+  if (pathname.endsWith('/')) {
+    pathname += 'index.html';
+  }
+
+  const safePath = path.normalize(pathname).replace(/^(\.\.(\/|\\|$))+/, '');
+  let filePath = path.join(rootDir, safePath);
+
+  if (!filePath.startsWith(rootDir)) {
+    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Forbidden');
+    return;
+  }
+
+  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
+    filePath = path.join(filePath, 'index.html');
+  } else if (!fs.existsSync(filePath) && fs.existsSync(filePath + '.html')) {
+    filePath = filePath + '.html';
+  }
+
+  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
+    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not Found');
+    return;
+  }
+
+  let contentType = MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
+  if (
+    pathname === '/.well-known/web-app-origin-association' ||
+    pathname === '/.well-known/web-app-origin-association.json'
+  ) {
+    contentType = 'application/json; charset=utf-8';
+  } else if (pathname === '/manifest.json' || pathname === '/manifest.webmanifest') {
+    contentType = 'application/manifest+json; charset=utf-8';
+  }
+
+  res.writeHead(200, { 'Content-Type': contentType, 'Cache-Control': 'no-cache' });
+  if (req.method === 'HEAD') {
+    res.end();
+    return;
+  }
+  fs.createReadStream(filePath).pipe(res);
+});
+
+function startListening(port) {
+  server.listen(port, values.expose ? undefined : 'localhost', () => {
+    const addr = server.address();
+    const boundPort = addr && typeof addr === 'object' ? addr.port : port;
+    const url = `http://localhost:${boundPort}`;
+    const formattedPath = rootDir.replace(os.homedir(), '~');
+    const reset = '\x1b[0m';
+    const boldWhite = '\x1b[1m\x1b[37m';
+    const dimWhite = '\x1b[2m\x1b[37m';
+    console.log(
+      boldWhite,
+      `🤓 ${url}`,
+      reset,
+      `statikk serving ${values.expose ? 'up' : 'locally'}:`,
+      `${dimWhite}${formattedPath}`,
+      reset
+    );
+  });
+}
+
+startListening(initialPort);
