@@ -0,0 +1,95 @@
+const CACHE_NAME = 'daily-grind-pwa-v1';
+const ASSETS = [
+  '/',
+  '/index.html',
+  '/install.html',
+  '/manifest.json',
+  '/manifest.webmanifest',
+  '/migration.js',
+  '/icons/icon-192.svg',
+  '/icons/icon-512.svg',
+  '/.well-known/web-app-origin-association'
+];
+
+const ORIGIN_ASSOCIATION_PAYLOAD = {
+  'https://app.dailygrind.com/': {
+    allow_migration: true,
+    scope: '/'
+  },
+  'https://new.dailygrind.com/': {
+    allow_migration: true,
+    scope: '/'
+  }
+};
+
+self.addEventListener('install', (event) => {
+  event.waitUntil(
+    caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS)).catch(() => {})
+  );
+  self.skipWaiting();
+});
+
+self.addEventListener('activate', (event) => {
+  event.waitUntil(
+    caches.keys().then((keys) =>
+      Promise.all(
+        keys
+          .filter((key) => key !== CACHE_NAME)
+          .map((key) => caches.delete(key))
+      )
+    )
+  );
+  self.clients.claim();
+});
+
+self.addEventListener('fetch', (event) => {
+  const url = new URL(event.request.url);
+
+  if (
+    url.pathname === '/.well-known/web-app-origin-association' ||
+    url.pathname === '/.well-known/web-app-origin-association.json'
+  ) {
+    event.respondWith(
+      fetch(event.request)
+        .then((response) => {
+          if (response && response.ok) {
+            return response;
+          }
+          return new Response(JSON.stringify(ORIGIN_ASSOCIATION_PAYLOAD, null, 2), {
+            status: 200,
+            headers: {
+              'Content-Type': 'application/json; charset=utf-8',
+              'Access-Control-Allow-Origin': '*'
+            }
+          });
+        })
+        .catch(() =>
+          new Response(JSON.stringify(ORIGIN_ASSOCIATION_PAYLOAD, null, 2), {
+            status: 200,
+            headers: {
+              'Content-Type': 'application/json; charset=utf-8',
+              'Access-Control-Allow-Origin': '*'
+            }
+          })
+        )
+    );
+    return;
+  }
+
+  if (event.request.method !== 'GET') return;
+
+  event.respondWith(
+    caches.match(event.request).then((cached) => {
+      const networkFetch = fetch(event.request)
+        .then((response) => {
+          if (response && response.status === 200 && url.origin === self.location.origin) {
+            const clone = response.clone();
+            caches.open(CACHE_NAME).then((cache) => cache.put(event.request, clone));
+          }
+          return response;
+        })
+        .catch(() => cached);
+      return cached || networkFetch;
+    })
+  );
+});

