+        } else if (e.key === 'ArrowLeft') {
+          e.preventDefault();
+          scrollToCard(getActiveCardIndex() - 1);
+        } else if (e.key === 'Home') {
+          e.preventDefault();
+          scrollToCard(0);
+        } else if (e.key === 'End') {
+          e.preventDefault();
+          scrollToCard(cards.length - 1);
+        }
+      });
+
+      // Pointer drag-to-swipe support for desktop and touch
+      let isPointerDown = false;
+      let hasDragged = false;
+      let startX = 0;
+      let startScrollLeft = 0;
+
+      track.addEventListener('pointerdown', (e) => {
+        if (e.target.closest('button, a')) return;
+        isPointerDown = true;
+        hasDragged = false;
+        startX = e.clientX;
+        startScrollLeft = track.scrollLeft;
+        track.classList.add('is-dragging');
+        if (track.setPointerCapture) {
+          try { track.setPointerCapture(e.pointerId); } catch (_) {}
+        }
+      });
+
+      track.addEventListener('pointermove', (e) => {
+        if (!isPointerDown) return;
+        const deltaX = e.clientX - startX;
+        if (Math.abs(deltaX) > 5) {
+          hasDragged = true;
+        }
+        track.scrollLeft = startScrollLeft - deltaX;
+      });
+
+      function endDrag() {
+        if (!isPointerDown) return;
+        isPointerDown = false;
+        track.classList.remove('is-dragging');
+        if (hasDragged) {
+          scrollToCard(getActiveCardIndex());
+        }
+      }
+
+      track.addEventListener('pointerup', endDrag);
+      track.addEventListener('pointercancel', endDrag);
+      track.addEventListener('pointerleave', endDrag);
+
+      // Expanding Detail View (Morphing directly out of the triggering "View Details" button)
+      const backdrop = document.getElementById('detail-backdrop');
+      const expander = document.getElementById('detail-expander');
+      const closeBtn = document.getElementById('detail-close-btn');
+      const dismissBtn = document.getElementById('detail-dismiss-btn');
+      const orderBtn = document.getElementById('detail-order-btn');
+      const toast = document.getElementById('toast-status');
+
+      const detailImg = document.getElementById('detail-img');
+      const detailBadge = document.getElementById('detail-badge');
+      const detailTitle = document.getElementById('detail-title');
+      const detailPrice = document.getElementById('detail-price');
+      const detailDesc = document.getElementById('detail-description');
+      const detailRoast = document.getElementById('detail-roast');
+      const detailCaffeine = document.getElementById('detail-caffeine');
+      const detailCalories = document.getElementById('detail-calories');
+      const detailIngredients = document.getElementById('detail-ingredients');
+
+      let activeTriggerBtn = null;
+      let isAnimating = false;
+      let currentDrinkTitle = '';
+
+      function showToast(message) {
+        toast.textContent = message;
+        toast.classList.add('is-visible');
+        clearTimeout(showToast._timer);
+        showToast._timer = setTimeout(() => {
+          toast.classList.remove('is-visible');
+        }, 3200);
+      }
+
+      function populateDetail(drinkId) {
+        const data = DRINK_DATA[drinkId];
+        if (!data) return;
+        currentDrinkTitle = data.title;
+        detailImg.src = data.image;
+        detailImg.alt = data.imageAlt;
+        detailBadge.textContent = data.badge;
+        detailTitle.textContent = data.title;
+        detailPrice.textContent = data.price;
+        detailDesc.textContent = data.description;
+        detailRoast.textContent = data.roast;
+        detailCaffeine.textContent = data.caffeine;
+        detailCalories.textContent = data.calories;
+        detailIngredients.textContent = data.ingredients;
+      }
+
+      function computeTargetBounds() {
+        const vw = window.innerWidth;
+        const vh = window.innerHeight;
+        const targetWidth = Math.min(540, vw - 32);
+        const targetHeight = Math.min(590, vh - 40);
+        const targetLeft = Math.round((vw - targetWidth) / 2);
+        const targetTop = Math.round((vh - targetHeight) / 2);
+        return { top: targetTop, left: targetLeft, width: targetWidth, height: targetHeight };
+      }
+
+      function openDetailFromButton(triggerBtn) {
+        if (isAnimating) return;
+        const drinkId = triggerBtn.getAttribute('data-drink-id');
