+++ b/src/pages/api/credential/[id].ts
@@ -0,0 +1,63 @@
+import type { APIRoute } from 'astro';
+import { db } from '../../../utils/passkeyStore';
+
+export const PUT: APIRoute = async ({ params, request }) => {
+  const id = params.id;
+  if (!id) {
+    return new Response(JSON.stringify({ error: 'Credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const user = await db.getCurrentUser();
+  const cred = await db.findCredentialById(id);
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const body = await request.json();
+  const name = typeof body?.name === 'string' ? body.name.trim() : '';
+  if (!name) {
+    return new Response(JSON.stringify({ error: 'Display name is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  cred.name = name;
+  const saved = await db.saveCredential(cred);
+
+  return new Response(JSON.stringify(saved), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
+
+export const DELETE: APIRoute = async ({ params }) => {
+  const id = params.id;
+  if (!id) {
+    return new Response(JSON.stringify({ error: 'Credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const user = await db.getCurrentUser();
+  const cred = await db.findCredentialById(id);
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  await db.deleteCredential(id);
+  return new Response(JSON.stringify({ success: true }), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
