+              {actionDescription ||
+                'For your security, The DevTools Times requires fresh passkey verification (User Verification = required) before performing sensitive account modifications.'}
+            </p>
+          </div>
+
+          {error && (
+            <div
+              className="p-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded-lg"
+              role="alert"
+            >
+              {error}
+            </div>
+          )}
+
+          {!usePasswordFallback ? (
+            <div className="space-y-4">
+              {passkeys.length > 0 && (
+                <div>
+                  <label
+                    htmlFor="reauth-passkey-select"
+                    className="block text-xs font-semibold uppercase tracking-wider text-gray-500 mb-1.5"
+                  >
+                    Select Registered Passkey
+                  </label>
+                  <select
+                    id="reauth-passkey-select"
+                    value={selectedCredentialId}
+                    onChange={(e) => setSelectedCredentialId(e.target.value)}
