+/**
+ * WebAuthn / Passkey utility library for The DevTools Times
+ * Provides authentic browser WebAuthn API (navigator.credentials.create & get) integration,
+ * base64url encoding/decoding, PublicKeyCredential serialization, conditional mediation (autofill),
+ * platform authenticator capability checks, and client/server passkey state persistence.
+ */
+
+export interface StoredPasskey {
+  id: string; // Base64URL credential ID
+  rawId: string; // Base64URL rawId
+  username: string;
+  userDisplayName: string;
+  userId: string; // Base64URL user handle
+  name: string; // Friendly device/passkey label (e.g., "Chrome on MacBook Pro", "iCloud Keychain")
+  publicKey?: string; // Base64URL SPKI or attestation object
+  algorithm: number; // COSEAlgorithmIdentifier (-7 for ES256, -257 for RS256)
+  transports: AuthenticatorTransport[];
+  authenticatorAttachment: 'platform' | 'cross-platform';
+  aaguid: string;
+  providerName: string;
+  createdAt: string; // ISO date
+  lastUsedAt: string | null; // ISO date or null
+  signCount: number;
+  backedUp: boolean;
+  backupEligible: boolean;
+  isDefault?: boolean;
+}
+
+export interface UserAccount {
+  id: string;
+  username: string;
+  email: string;
+  displayName: string;
+  role: string;
+  subscriptionTier: 'Free' | 'Digital Subscriber' | 'All-Access Patron';
+  passwordlessEnabled: boolean;
+  requireReauthForSensitiveActions: boolean;
+  lastReauthAt: string | null;
+  createdAt: string;
+}
+
+export interface SecurityAuditEvent {
+  id: string;
+  timestamp: string;
+  type:
+    | 'passkey_registered'
+    | 'passkey_authenticated'
+    | 'passkey_reauthenticated'
+    | 'passkey_renamed'
+    | 'passkey_revoked'
+    | 'password_login'
+    | 'settings_updated'
+    | 'webauthn_ceremony_failed';
+  title: string;
+  description: string;
+  credentialId?: string;
+  deviceInfo?: string;
+  status: 'success' | 'warning' | 'error';
+}
+
+const STORAGE_KEYS = {
+  PASSKEYS: 'dtt_passkeys_v1',
+  CURRENT_USER: 'dtt_current_user_v1',
+  ACCOUNTS: 'dtt_accounts_v1',
+  AUDIT_LOG: 'dtt_security_audit_v1',
+  REAUTH_TIMESTAMP: 'dtt_last_reauth_ts_v1',
+  SIMULATION_FALLBACK: 'dtt_webauthn_fallback_enabled_v1',
+};
+
+// Known Authenticator AAGUID catalog for realistic device metadata display
+export const KNOWN_AAGUIDS: Record<string, { name: string; icon: string }> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', icon: 'google' },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain', icon: 'apple' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello', icon: 'windows' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', icon: 'key' },
