+  }
+  if (/Windows/i.test(ua)) {
+    return {
+      deviceName: 'Windows PC (Windows Hello)',
+      providerName: 'Windows Hello',
+      aaguid: '08987058-cadc-4b81-b6e1-30de50dcbe96',
