+  <script>
+    (function () {
+      const container = document.getElementById('toast-container');
+
+      function dismissToast(toast) {
+        if (!toast || toast.dataset.dismissing === 'true') return;
+        toast.dataset.dismissing = 'true';
+        toast.classList.remove('show');
+        toast.classList.add('toast-hide');
+
+        const removeEl = () => {
+          if (toast.parentNode) {
+            toast.parentNode.removeChild(toast);
+          }
+        };
+
+        toast.addEventListener('animationend', removeEl, { once: true });
+        toast.addEventListener('transitionend', removeEl, { once: true });
+        setTimeout(removeEl, 350);
+      }
+
+      function createToast({ title = 'Notification', message = 'Action completed successfully!', duration = 4000 } = {}) {
+        const toast = document.createElement('div');
+        toast.className = 'toast show';
+        toast.setAttribute('role', 'status');
+
+        const content = document.createElement('div');
+        content.className = 'toast-content';
+
+        if (title) {
+          const titleEl = document.createElement('div');
+          titleEl.className = 'toast-title';
+          titleEl.textContent = title;
+          content.appendChild(titleEl);
+        }
+
+        const msgEl = document.createElement('div');
+        msgEl.className = 'toast-message';
+        msgEl.textContent = message;
+        content.appendChild(msgEl);
+
+        const closeBtn = document.createElement('button');
+        closeBtn.className = 'toast-close';
+        closeBtn.setAttribute('aria-label', 'Dismiss notification');
+        closeBtn.innerHTML = '&times;';
+        closeBtn.addEventListener('click', () => dismissToast(toast));
+
+        toast.appendChild(content);
+        toast.appendChild(closeBtn);
+        container.appendChild(toast);
+
+        if (duration > 0) {
+          setTimeout(() => dismissToast(toast), duration);
+        }
+
+        return toast;
+      }
+
+      document.addEventListener('click', (event) => {
+        const trigger = event.target.closest('.toast-trigger');
+        if (!trigger) return;
+
+        event.preventDefault();
+
+        const title = trigger.dataset.toastTitle || 'The Daily Grind';
+        const message =
+          trigger.dataset.toastMessage ||
+          trigger.dataset.toast ||
+          `${trigger.textContent.trim()} notification triggered.`;
+
+        createToast({ title, message });
+      });
+
+      window.showToast = createToast;
+    })();
+  </script>
 </body>

