+          letter-spacing: 0.05em;
+          padding: 3px 10px;
+          border-radius: 999px;
+          margin-bottom: 8px;
+        }
+
+        .badge[hidden] {
+          display: none;
+        }
+
+        .title {
+          margin: 0 0 10px;
+          color: var(--_primary);
+          font-size: 1.17rem;
+        }
+
+        ::slotted([slot="title"]) {
+          margin: 0;
+          color: inherit;
+          font: inherit;
+        }
+
+        .description,
+        .desc-fallback {
+          margin: 0;
+        }
+
+        .desc-fallback:empty {
+          display: none;
+        }
+
+        ::slotted(p),
+        ::slotted([slot="description"]) {
+          margin: 0;
+        }
+
+        .action-link,
+        ::slotted(a[slot="action"]) {
+          display: inline-block;
+          background: var(--_primary);
+          color: #ffffff;
+          padding: 10px 20px;
+          text-decoration: none;
+          border-radius: 5px;
+          margin-top: 15px;
+          font: inherit;
+          transition: background 0.3s;
+        }
+
+        .action-link:hover,
+        ::slotted(a[slot="action"]:hover) {
+          background: var(--_text);
+        }
+
+        .action-link[hidden] {
+          display: none;
+        }
+      }
+    `);
