+            break;
+          case 'heading':
+            this.#syncHeading();
+            break;
+          case 'description':
+            this.#syncDescription();
+            break;
+          case 'href':
+          case 'action-label':
+            this.#syncAction();
+            break;
+        }
+      }
+
+      #syncAll() {
+        this.#syncBadge();
+        this.#syncHeading();
+        this.#syncDescription();
+        this.#syncAction();
