+    (function () {
+      const table = document.getElementById('seasonal-drinks');
+      if (!table) return;
+
+      const headers = table.querySelectorAll('thead th');
+      const tbody = table.querySelector('tbody');
+
+      function parseCellValue(cell) {
+        const raw = cell.getAttribute('data-value') ?? cell.textContent.trim();
+        const numericCleaned = raw.replace(/[^0-9.-]+/g, '');
+        if (numericCleaned !== '' && /^[$€£]?\s*-?\d+(\.\d+)?\s*(mg|cal|oz|%)?$/i.test(raw)) {
+          return { type: 'number', value: parseFloat(numericCleaned) };
+        }
+        return { type: 'string', value: raw.toLowerCase() };
+      }
+
+      headers.forEach((header, index) => {
+        header.addEventListener('click', () => {
+          const currentDir = header.getAttribute('data-sort-dir');
+          const nextDir = currentDir === 'asc' ? 'desc' : 'asc';
+
+          headers.forEach((h) => {
+            h.removeAttribute('data-sort-dir');
+            h.setAttribute('aria-sort', 'none');
+          });
+
+          header.setAttribute('data-sort-dir', nextDir);
+          header.setAttribute('aria-sort', nextDir === 'asc' ? 'ascending' : 'descending');
+
+          const rows = Array.from(tbody.querySelectorAll('tr'));
+          rows.sort((rowA, rowB) => {
+            const cellA = rowA.children[index];
+            const cellB = rowB.children[index];
+            const valA = parseCellValue(cellA);
+            const valB = parseCellValue(cellB);
+
+            let comparison = 0;
+            if (valA.type === 'number' && valB.type === 'number') {
+              comparison = valA.value - valB.value;
+            } else {
+              comparison = String(valA.value).localeCompare(String(valB.value));
+            }
+
+            return nextDir === 'asc' ? comparison : -comparison;
+          });
+
+          rows.forEach((row) => tbody.appendChild(row));
+        });
+      });
+    })();
+  </script>
