+            { col: 0, row: 0, span: 2 },
+            { col: 2, row: 0, span: 1 },
+            { col: 0, row: 1, span: 1 },
+            { col: 1, row: 1, span: 2 },
+            { col: 0, row: 2, span: 1 },
+            { col: 1, row: 2, span: 1 },
+          ];
+          return cards.map((card, index) => {
+            const spec = masonryCoords[index] || { col: index % 3, row: Math.floor(index / 3), span: 1 };
+            const left = spec.col * (cellW + gap);
+            const top = spec.row * (cellH + gap);
+            const width = spec.span * cellW + (spec.span - 1) * gap;
+            return {
+              card,
+              index,
+              left,
+              right: left + width,
+              top,
+              bottom: top + cellH,
+              width,
+              height: cellH,
