+
+      /**
+       * Groups cards into visual rows based on vertical overlap / center proximity.
+       * Within each row, cards are sorted left-to-right (or right-to-left in RTL).
+       */
+      function getVisualRows(items, isRTL) {
+        if (items.length === 0) return [];
+
+        const sortedByTop = [...items].sort((a, b) => {
+          if (Math.abs(a.top - b.top) > 8) return a.top - b.top;
+          return isRTL ? b.left - a.left : a.left - b.left;
