+            if (Math.abs(item.cy - rowMid) <= tolerance || Math.abs(item.top - rowTop) <= 12) {
+              row.push(item);
+              placed = true;
+              break;
+            }
+          }
+          if (!placed) {
+            rows.push([item]);
+          }
+        }
+
+        for (const row of rows) {
+          row.sort((a, b) => (isRTL ? b.cx - a.cx : a.cx - b.cx));
+        }
+
+        return rows;
+      }
+
+      /**
+       * Spatial navigation resolver using 2D bounding-box geometry and visual row grouping.
+       * Supports ArrowRight, ArrowLeft, ArrowDown, ArrowUp, Home, End.
+       */
+      function findNextSpatialCard(currentCard, key) {
+        const cards = getCards();
+        if (cards.length === 0) return null;
+
+        const currentIndex = cards.indexOf(currentCard);
+        if (currentIndex === -1) return cards[0];
+
+        if (key === 'Home') return cards[0];
+        if (key === 'End') return cards[cards.length - 1];
+
+        const isRTL =
+          window.getComputedStyle(grid).direction === 'rtl' ||
+          document.documentElement.dir === 'rtl';
+
+        const items = getCardRects(cards);
+        const current = items[currentIndex];
+        const rows = getVisualRows(items, isRTL);
+
+        let currentRowIdx = -1;
+        let currentColIdx = -1;
+        for (let r = 0; r < rows.length; r++) {
+          const c = rows[r].findIndex((item) => item.card === currentCard);
+          if (c !== -1) {
+            currentRowIdx = r;
+            currentColIdx = c;
+            break;
+          }
+        }
+
+        const effectiveKey =
+          isRTL && (key === 'ArrowRight' || key === 'ArrowLeft')
+            ? key === 'ArrowRight'
+              ? 'ArrowLeft'
+              : 'ArrowRight'
+            : key;
+
+        // Horizontal movement: move across the current visual row, or wrap into adjacent visual row
+        if (effectiveKey === 'ArrowRight') {
+          if (currentRowIdx !== -1) {
+            const row = rows[currentRowIdx];
+            if (currentColIdx + 1 < row.length) {
+              return row[currentColIdx + 1].card;
+            }
+            if (currentRowIdx + 1 < rows.length) {
+              return rows[currentRowIdx + 1][0].card;
+            }
+          }
+          return null;
+        }
+
+        if (effectiveKey === 'ArrowLeft') {
+          if (currentRowIdx !== -1) {
+            const row = rows[currentRowIdx];
+            if (currentColIdx - 1 >= 0) {
+              return row[currentColIdx - 1].card;
+            }
+            if (currentRowIdx - 1 >= 0) {
+              const prevRow = rows[currentRowIdx - 1];
+              return prevRow[prevRow.length - 1].card;
+            }
+          }
+          return null;
+        }
+
+        // Vertical movement (ArrowDown / ArrowUp):
+        // 1. Prefer the immediately adjacent visual row (next row for Down, previous row for Up)
+        //    and pick the card with maximum horizontal overlap or closest horizontal center.
+        // 2. If custom geometry places cards outside standard rows, fall back to directional 2D cone metric.
+        if (effectiveKey === 'ArrowDown' || effectiveKey === 'ArrowUp') {
+          const dir = effectiveKey === 'ArrowDown' ? 1 : -1;
+          const targetRowIdx = currentRowIdx + dir;
+
+          if (currentRowIdx !== -1 && targetRowIdx >= 0 && targetRowIdx < rows.length) {
+            const candidateRow = rows[targetRowIdx];
+            return pickBestHorizontalMatch(current, candidateRow).card;
+          }
