+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.ico': 'image/x-icon',
+};
+
+const server = http.createServer(async (req, res) => {
+  try {
+    const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+
+    if (req.method === 'POST' && (url.pathname === '/api/verify-email' || url.pathname === '/api/rewards/signup')) {
+      await handleSignupSubmission(req, res);
+      return;
+    }
+
+    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+      const { nonce } = getOrCreateSession(req, res);
+      const htmlPath = path.join(__dirname, 'index.html');
+      let html = await fs.readFile(htmlPath, 'utf-8');
+      html = html
+        .replaceAll('SERVER_GENERATED_PER_FORM_NONCE', nonce)
+        .replaceAll('__ORIGIN_TRIAL_TOKEN__', ORIGIN_TRIAL_TOKEN);
+
+      res.writeHead(200, {
+        'Content-Type': 'text/html; charset=utf-8',
+        'Cache-Control': 'no-store',
+        'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+      });
+      res.end(html);
+      return;
+    }
+
+    if (req.method === 'GET') {
+      const safePath = path.normalize(url.pathname).replace(/^(\.\.(\/|\\|$))+/, '');
+      const filePath = path.join(__dirname, safePath);
+      const ext = path.extname(filePath);
+      const data = await fs.readFile(filePath);
+      res.writeHead(200, {
+        'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
+      });
+      res.end(data);
+      return;
+    }
+
+    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not Found');
+  } catch (err) {
+    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not Found');
+  }
+});
